import{_ as o,c as a,e as s,a as e,d as n,w as r,r as i,o as l,b as d}from"./app-CHV3pEDi.js";const c="/assets/p1-bVGO4Yjn.png",h="/assets/%E6%8C%89%E9%94%AE%E4%B8%AD%E6%96%AD%E5%AE%9E%E6%97%B6%E5%93%8D%E5%BA%94%E6%97%B6%E5%BA%8F%E5%9B%BE-BWTh0Lg4.jpg",m="/assets/%E4%B8%A4%E7%B1%BB%E7%B3%BB%E7%BB%9F%E5%93%8D%E5%BA%94%E7%A1%AE%E5%AE%9A%E6%80%A7%E5%AF%B9%E6%AF%94%E5%9B%BE-CfZT_gFe.jpg",E="/assets/%E6%8A%A2%E5%8D%A0%E5%BC%8F%E8%B0%83%E5%BA%A6%E5%93%8D%E5%BA%94%E6%97%B6%E5%BA%8F%E5%9B%BE-C83Adrgw.jpg",R={};function g(O,t){const p=i("VPLink");return l(),a("div",null,[t[4]||(t[4]=s('<p>我们知道，RTOS的全称是（Realtime Operating System）。有的同学可能对其中的Realtime产生这样的误解：</p><blockquote><p>&quot;实时（Realtime）&quot;是不是指系统运速度快吗？</p><p>Windows跑在高性能处理器上，速度肯定比跑在单片机上的RTOS快，那为什么人们不说Windows是RTOS？</p></blockquote><p>那么，RTOS的&quot;实时&quot;到底是什么意思？在这篇文章中，我将详细解答这个问题。</p><h2 id="先从银行办业务说起" tabindex="-1"><a class="header-anchor" href="#先从银行办业务说起"><span>先从银行办业务说起</span></a></h2><p>在正式讲“实时”概念之前，我们先来看一个生活中的现象。</p><p>假设你去银行办业务，大厅里有两个窗口，它们都叫号排队。 <img src="'+c+'" alt="p1.png"> 第一个窗口的业务员手脚麻利、一天能办很多业务，但安排很灵活，会根据现场情况随时调整。比如优先办简单业务、给VIP让路。这样整体效率很高，但是你却没法准确知道自己几点能办上。</p><p>第二个窗口的业务员速度稍慢，但规则明确、不随便更改：紧急业务走绿色通道优先，普通业务严格按号码顺序来。你拿到号，就能准确知道自己还要等多久。</p><p>对比两个窗口可以发现：办理速度快、办的总量多，并不等于能在可预期的时间内办上业务。</p><p>我们可以将这两个窗口对应两类操作系统：</p><blockquote><p>第一个类似Windows，追求的是吞吐量、调度灵活，不过单个任务的响应时间不好预测； 第二个类似RTOS，规则明确、优先级严格，关键业务一定能在可预期的时间内得到处理。</p></blockquote><p>这两者没有一定谁优谁劣的问题，而是各自适用的场合不同。</p><h2 id="实时-不是快-而是确定" tabindex="-1"><a class="header-anchor" href="#实时-不是快-而是确定"><span>&quot;实时&quot;不是快，而是确定</span></a></h2><p>要弄清楚这个问题，我们先要明白&quot;实时&quot;这两个字到底是什么意思。</p><p><strong>所谓实时，指的是系统能够在规定的时间内，对外部发生的事件做出响应并完成处理</strong>。这个规定的时间，通常叫做截止时间。换句话说，<strong>实时强调的并不是算得快，而是在要求的时间之内一定能把事情做完。</strong></p><p><strong>因此，对于RTOS而言，它追求的并不是速度快，而是指确定性。</strong> 比如，给定一个任务，我们能够准确地知道它最晚在什么时候能够得到响应。</p><p>例如，假设有一个任务，需要在按键按下之后的10毫秒内做出响应。</p><p>在Windows系统中，常常会发现由于某个软件卡死，使得我们按下按键后没有任何反应、鼠标也无法拖动。这是因为Windows这类通用操作系统更注重吞吐量和公平性，任务的响应时间受到很多因素的影响，如当前有多少任务在运行、系统负载高不高等等。</p><p>而在RTOS里，可以把任务设置为高优先级，只要按键中断触发、任务就绪，调度器就会立刻让这个任务运行。这使得它的响应时间是有上限的、可预测的，也就是说可以在最迟多少时间（比如10ms）内得到处理。</p><p><img src="'+h+'" alt="按键中断实时响应时序图"></p><p>由此可见，面对同一个事件，RTOS能保证响应时间有上限；而普通操作系统，则无法提供这种保证。</p><p><img src="'+m+'" alt="两类系统响应确定性对比图"></p><h2 id="为什么rtos能做到确定性" tabindex="-1"><a class="header-anchor" href="#为什么rtos能做到确定性"><span>为什么RTOS能做到确定性</span></a></h2><p>那么，RTOS是怎么做到响应时间可预测的呢？</p><p>具体来说，RTOS主要通过抢占式调度、可预测的中断响应和时间片轮转等机制来实现确定性。</p><p>这里仍然以前面的按键为例，逐个分析这些机制所发挥的作用。</p><p><img src="'+E+'" alt="抢占式调度响应时序图"></p><h3 id="抢占式调度" tabindex="-1"><a class="header-anchor" href="#抢占式调度"><span>抢占式调度</span></a></h3><p>当按键中断唤醒高优先级任务之后，调度器会立即切换到高优先级任务运行，从而实现抢占式调度，从而保证按键这一件事情能够尽快得到执行，而不会受其他低优先级任务运行的影响。</p><p>在实际开发中，<strong>我们把关键任务设置为高优先级、非关键任务设置为低优先级</strong>。如此一来，关键任务的响应时间也就有了保障。</p><h3 id="可预测的中断响应时间" tabindex="-1"><a class="header-anchor" href="#可预测的中断响应时间"><span>可预测的中断响应时间</span></a></h3><p>当中断触发之后，任务唤醒任务、上下文切换这些动作的执行路径都是固定的，它们所花费的时间也就有了明确的上限。</p><p>通常情况下，RTOS的中断处理过程通常比较短小，关中断的临界区也很短，这就保证了从按键事件发生到任务运行之间的时间是可预测的。</p><h3 id="时间片轮转" tabindex="-1"><a class="header-anchor" href="#时间片轮转"><span>时间片轮转</span></a></h3><p>当面临系统中多个任务拥有相同优先级的情况下，会不会出现某个任务长时间占用CPU运行，导致按键处理任务迟迟无法运行，使得按键的响应时间变得不可预测？</p><p>不会。对于优先级相同的任务，RTOS通常采用时间片轮转的方式，让每个任务轮流运行一段时间。这样既保证了同优先级任务之间的公平性，又不会让某个任务长时间独占CPU。</p><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p>综上所述，<strong>RTOS中的&quot;实时&quot;不是指速度快，而是指确定性，也就是系统的响应时间是可预测的</strong>。</p><p>RTOS通过抢占式调度、可预测的中断响应时间、时间片轮转来保证实时性，让关键任务能在截止时间之前完成。</p><p>普通操作系统虽然在高性能处理器上运行速度可能更快，但它的响应时间是不可预测的，不能保证关键任务总能在截止时间之前完成，所以它不是实时操作系统。</p><hr>',40)),e("blockquote",null,[t[1]||(t[1]=e("p",null,"如果你希望系统地学习RTOS底层原理，可以了解我的《RTOS开发与实战》课程。",-1)),t[2]||(t[2]=e("p",null,"课程不是简单地讲解FreeRTOS API的使用，而是带你从零开始编写一个RTOS内核，逐步实现任务管理、任务调度、上下文切换、同步与通信等核心机制，并通过一个远程温湿度监控设备项目，将操作系统原理应用到实际嵌入式开发中。",-1)),t[3]||(t[3]=e("p",null,"适合希望深入理解RTOS工作原理、提升嵌入式底层开发能力的同学。",-1)),e("p",null,[n(p,{href:"/blog/diyrtos/"},{default:r(()=>[...t[0]||(t[0]=[d("课程详情",-1)])]),_:1})])])])}const T=o(R,[["render",g]]),u=JSON.parse('{"path":"/tech/rtos100/7ttjonpz/","title":"RTOS中的实时到底是什么意思","lang":"zh-CN","frontmatter":{"title":"RTOS中的实时到底是什么意思","createTime":"2026/11/10 14:55:12","permalink":"/tech/rtos100/7ttjonpz/","description":"我们知道，RTOS的全称是（Realtime Operating System）。有的同学可能对其中的Realtime产生这样的误解： \\"实时（Realtime）\\"是不是指系统运速度快吗？ Windows跑在高性能处理器上，速度肯定比跑在单片机上的RTOS快，那为什么人们不说Windows是RTOS？ 那么，RTOS的\\"实时\\"到底是什么意思？在这篇文章...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"RTOS中的实时到底是什么意思\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://lishutong1024.cn/tech/rtos100/7ttjonpz/"}],["meta",{"property":"og:site_name","content":"李述铜的嵌入式课堂"}],["meta",{"property":"og:title","content":"RTOS中的实时到底是什么意思"}],["meta",{"property":"og:description","content":"我们知道，RTOS的全称是（Realtime Operating System）。有的同学可能对其中的Realtime产生这样的误解： \\"实时（Realtime）\\"是不是指系统运速度快吗？ Windows跑在高性能处理器上，速度肯定比跑在单片机上的RTOS快，那为什么人们不说Windows是RTOS？ 那么，RTOS的\\"实时\\"到底是什么意思？在这篇文章..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":5.84,"words":1753},"git":{},"autoDesc":true,"filePathRelative":"notes/tech/rtos100/base/q03.md","headers":[],"bulletin":true}');export{T as comp,u as data};
